contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint n1, uint n2) public {
        require(n1 != n2);
        require(n1 > 0 && n1 < 4);
        require(n2 > 0 && n2 < 4);

        address f0 = c.from();
        address ca0 = c.caddress();

        address[] memory tos = new address[](n1);
        uint[] memory vs = new uint[](n2);
        for (uint i = 0; i < n1; i++) { tos[i] = address(uint160(i + 1)); }
        for (uint i = 0; i < n2; i++) { vs[i] = 1; }

        bool reverted;
        try c.transfer(tos, vs) { reverted = false; }
        catch { reverted = true; }

        assert(reverted && c.from() == f0 && c.caddress() == ca0);
    }
}
